package com.manishrawat.realestate.servlet; import com.manishrawat.realestate.model.User; import com.manishrawat.realestate.service.AuthService; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*;
@WebServlet("/login") public class LoginServlet extends HttpServlet {private final AuthService auth=new AuthService(); protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{User u=auth.login(r.getParameter("email"),r.getParameter("password"));if(u==null){s.sendRedirect(r.getContextPath()+"/?error=Invalid%20login");return;}r.getSession().setAttribute("user",u);s.sendRedirect(r.getContextPath()+"/dashboard");}catch(Exception e){throw new IOException(e);}}}
